namespace Health_Care_System.BLL.Models;
public sealed class PaginatedList<T>:List<T>{ public int PageIndex{get;} public int TotalPages{get;} public int TotalCount{get;} public bool HasPreviousPage=>PageIndex>1; public bool HasNextPage=>PageIndex<TotalPages; private PaginatedList(IEnumerable<T> items,int count,int pageIndex,int pageSize):base(items){PageIndex=pageIndex;TotalPages=(int)Math.Ceiling(count/(double)pageSize);TotalCount=count;} public static PaginatedList<T> Create(IEnumerable<T> source,int pageIndex,int pageSize){pageIndex=Math.Max(1,pageIndex);pageSize=Math.Max(1,pageSize);var items=source.ToList();return new(items.Skip((pageIndex-1)*pageSize).Take(pageSize),items.Count,pageIndex,pageSize);} }
